{
  "technical_and_design_decisions": [
    "All documentation deliverables will be stored in the official Hyperledger Fabric documentation repository, versioned in sync with code releases to ensure alignment between documentation and implementation.",
    "The sanity check for invocation restrictions (U7) will be implemented as a pre-processing validation step in the peer's chaincode invocation handler to block unauthorized invocations before they are processed.",
    "The Node.js SDK (U8) will adhere to the existing API design patterns used in the Go and Java Fabric SDKs to ensure consistency across client libraries.",
    "Ledger code and test refactoring (U4) will follow the block structure specification defined in the merged Gerrit change 2581 referenced in the specification.",
    "Demo materials for U5 will be built against the v1.0 codebase as of sprint 6 end (late November) as the reference implementation.",
    "Versioned documentation will use clear, prominent notices to direct users requiring a stable production platform to v0.6 documentation, while v1.0 docs will be marked as in-development."
  ],
  "assumptions": [
    "The FAB-687 API for new channel configuration transactions is fully implemented and available for reference when completing U2 documentation work.",
    "The Gerrit changes 1795 (new channel config transaction) and 2581 (new block structure) are merged and accessible for use in U2 and U4 work respectively.",
    "The existing peer, chaincode lifecycle, and ledger codebases are stable enough to support the refactoring, validation, and documentation work required for the increment.",
    "Target audiences for documentation and demo materials have baseline familiarity with blockchain concepts and Hyperledger Fabric fundamentals, so no introductory blockchain content is required.",
    "The Node SDK will implement a minimum viable set of core Fabric operations (channel creation, chaincode install/instantiate/invoke/query) to meet the requirements of U8 for the increment."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "New visitor onboarding documentation development",
      "activity_description": "Create a quick start guide for new Hyperledger Fabric users including environment setup steps, and restructure documentation navigation to enable easy discovery of relevant content per U1",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "New channel configuration transaction documentation",
      "activity_description": "Document the fields, values, and structure of the new channel configuration transaction created by the FAB-687 API, reference implementation details from merged Gerrit change 1795, per U2",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Peer and chaincode upgrade procedure documentation",
      "activity_description": "Create documentation covering peer protocol upgrades without data loss, chaincode upgrades via lifecycle management, patch application via SCC, and migration steps for protocol changes and security vulnerabilities, per U3",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A4",
      "activity_name": "Ledger code and test refactoring",
      "activity_description": "Update all ledger implementation code and associated unit tests to use the new block structure from merged Gerrit change 2581, remove explicit MSP security dependencies from ledger unit tests, and validate all tests pass, per U4",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A5",
      "activity_name": "v1.0 architecture and behavior demo material development",
      "activity_description": "Develop visual architecture diagrams, executable demo scripts, and step-by-step walkthrough materials showcasing Fabric v1.0 (sprint 6 end) architecture and behavior for collaborators and potential customers, per U5",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6",
      "activity_name": "Versioned Fabric documentation development and maintenance",
      "activity_description": "Create initial v1.0 usage documentation aligned with current development progress, add prominent notices directing users to v0.6 for stable production use, and establish a process to keep documentation synchronized with code changes, per U6",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A7",
      "activity_name": "Invocation sanity check implementation",
      "activity_description": "Add pre-invoke validation logic to the peer to restrict invocations exclusively to LCCC (Lifecycle System Chaincode) and normal user chaincode, reject all other invocation types, and add unit tests for the validation logic, per U7",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A8",
      "activity_name": "Node.js SDK development",
      "activity_description": "Implement core Node.js SDK with client APIs for channel management, chaincode install/instantiate/invoke/query operations, include sample application code, and write SDK usage documentation, per U8",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 41
  }
}

